<?php require __DIR__.'/common.php';require __DIR__.'/event_catalogue.php';[$search,$category,$period]=catalogueFilters();$events=fetchCatalogue();pageStart('Browse events'); ?>
<h1>Find your next event</h1><p>Explore upcoming experiences or look back at past events.</p><?php catalogueForm($search,$category,$period,'events.php'); ?><p><?=count($events)?> event(s) found</p><div class="cards"><?php foreach($events as $e):$group=eventPeriod($e); ?>
<article class="card"><img src="assets/<?=h(eventArtwork($e))?>" alt=""><div class="card-body"><p class="label"><?=h($e['category'])?> · <?=h($group==='unscheduled'?'Dates pending':ucfirst($group))?></p><h2><?=h($e['event_name'])?></h2><p><?=h($e['venue_name'].' · '.$e['location'])?></p><p><?=h($e['next_session']??$e['last_session']??'Dates to be announced')?></p><p><?=$group==='past'?'Previous ticket prices from':'From'?> <?=money($e['starting_price']??0)?></p><a class="button" href="event.php?event=<?=h($e['event_id'])?>"><?=$group==='upcoming'?'View event & book':'View event'?></a></div></article><?php endforeach; ?></div><?php if(!$events): ?><section class="panel"><p>No events match these filters.</p><a href="events.php?period=all">View all events</a></section><?php endif; ?><?php pageEnd(); ?>
